                "Pipeline chains the bridge to the model: preprocessing steps + estimator in one object with a single .fit/.predict. This isn't tidiness \u2014 it's leakage prevention (transformers fit on train folds only, automatically).",
                "get_feature_names_out() recovers column names after transformation \u2014 essential for feature importance, debugging, and explaining the model to stakeholders who think in column names, not 'feature 37.'",
